import React, { useState, useEffect } from 'react';
import api from '../services/api';
import EventCard from '../components/EventCard';
import LoadingSpinner from '../components/LoadingSpinner';

const Events = () => {
    const [events, setEvents] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({
        search: '',
        category: 'all',
        location: 'all',
        date: 'all'
    });
    const [categories, setCategories] = useState([]);
    const [locations, setLocations] = useState(['all']);
    const [pagination, setPagination] = useState({
        currentPage: 1,
        totalPages: 1,
        totalEvents: 0
    });

    // Predefined categories from schema
    const categoryOptions = [
        'all',
        'Conference',
        'Workshop',
        'Seminar',
        'Networking',
        'Social',
        'Other'
    ];

    useEffect(() => {
        fetchCategories();
        fetchEvents();
    }, []);

    useEffect(() => {
        fetchEvents();
    }, [filters, pagination.currentPage]);

    const fetchCategories = async () => {
        try {
            const response = await api.get('/events/categories');
            setCategories(['all', ...response.data]);
        } catch (error) {
            console.error('Error fetching categories:', error);
            // Fallback to predefined categories if API fails
            setCategories(categoryOptions);
        }
    };

    const fetchEvents = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                page: pagination.currentPage,
                limit: 9
            });

            if (filters.search) params.append('search', filters.search);
            if (filters.category !== 'all') params.append('category', filters.category);
            if (filters.location !== 'all') params.append('location', filters.location);
            if (filters.date !== 'all') params.append('date', filters.date);

            const response = await api.get(`/events?${params}`);
            setEvents(response.data.events);
            setPagination({
                currentPage: response.data.currentPage,
                totalPages: response.data.totalPages,
                totalEvents: response.data.totalEvents
            });

            // Update locations from response
            if (response.data.locations) {
                setLocations(['all', ...response.data.locations]);
            }
        } catch (error) {
            console.error('Error fetching events:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleFilterChange = (e) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
        setPagination(prev => ({ ...prev, currentPage: 1 }));
    };

    const handleSearch = (e) => {
        e.preventDefault();
        fetchEvents();
    };

    const handlePageChange = (newPage) => {
        setPagination(prev => ({ ...prev, currentPage: newPage }));
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const resetFilters = () => {
        setFilters({
            search: '',
            category: 'all',
            location: 'all',
            date: 'all'
        });
        setPagination(prev => ({ ...prev, currentPage: 1 }));
    };

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="container mx-auto px-4">
                <h1 className="text-3xl font-bold mb-8 text-gray-800">
                    Browse Events
                </h1>

                {/* Filters */}
                <div className="bg-white rounded-lg shadow p-6 mb-8">
                    <form onSubmit={handleSearch}>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-4">
                            {/* Search Input */}
                            <div className="lg:col-span-2">
                                <input
                                    type="text"
                                    name="search"
                                    placeholder="Search events by name, description, location..."
                                    value={filters.search}
                                    onChange={handleFilterChange}
                                    className="w-full border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600"
                                />
                            </div>
                            
                            {/* Category Dropdown */}
                            <div>
                                <select
                                    name="category"
                                    value={filters.category}
                                    onChange={handleFilterChange}
                                    className="w-full border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600 bg-white"
                                >
                                    {categoryOptions.map(cat => (
                                        <option key={cat} value={cat}>
                                            {cat === 'all' ? 'All Categories' : cat}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Location Dropdown */}
                            <div>
                                <select
                                    name="location"
                                    value={filters.location}
                                    onChange={handleFilterChange}
                                    className="w-full border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600 bg-white"
                                >
                                    {locations.map(loc => (
                                        <option key={loc} value={loc}>
                                            {loc === 'all' ? 'All Locations' : loc}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Date Dropdown */}
                            <div>
                                <select
                                    name="date"
                                    value={filters.date}
                                    onChange={handleFilterChange}
                                    className="w-full border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600 bg-white"
                                >
                                    <option value="all">All Dates</option>
                                    <option value="today">Today</option>
                                    <option value="tomorrow">Tomorrow</option>
                                    <option value="this-week">This Week</option>
                                    <option value="this-month">This Month</option>
                                </select>
                            </div>
                        </div>

                        <div className="flex justify-between items-center">
                            <button
                                type="submit"
                                className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 transition"
                            >
                                Apply Filters
                            </button>
                            
                            <button
                                type="button"
                                onClick={resetFilters}
                                className="text-gray-600 hover:text-gray-800 transition"
                            >
                                Clear Filters
                            </button>
                        </div>
                    </form>
                </div>

                {/* Results */}
                {loading ? (
                    <LoadingSpinner />
                ) : (
                    <>
                        <div className="flex justify-between items-center mb-4">
                            <p className="text-gray-600">
                                Found <span className="font-bold text-purple-600">{pagination.totalEvents}</span> events
                            </p>
                            {filters.category !== 'all' && (
                                <p className="text-sm text-gray-500">
                                    Filtered by: <span className="font-semibold">{filters.category}</span>
                                </p>
                            )}
                        </div>

                        {events.length === 0 ? (
                            <div className="text-center py-12">
                                <p className="text-gray-500 text-lg mb-4">No events found matching your criteria</p>
                                <button
                                    onClick={resetFilters}
                                    className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 transition"
                                >
                                    Clear Filters
                                </button>
                            </div>
                        ) : (
                            <>
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                                    {events.map(event => (
                                        <EventCard key={event._id} event={event} />
                                    ))}
                                </div>

                                {/* Pagination */}
                                {pagination.totalPages > 1 && (
                                    <div className="flex justify-center mt-8 space-x-2">
                                        <button
                                            onClick={() => handlePageChange(pagination.currentPage - 1)}
                                            disabled={pagination.currentPage === 1}
                                            className="px-4 py-2 border rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100 transition"
                                        >
                                            Previous
                                        </button>
                                        
                                        {[...Array(pagination.totalPages)].map((_, i) => {
                                            const pageNum = i + 1;
                                            // Show only current page, first, last, and adjacent pages
                                            if (
                                                pageNum === 1 ||
                                                pageNum === pagination.totalPages ||
                                                Math.abs(pageNum - pagination.currentPage) <= 2
                                            ) {
                                                return (
                                                    <button
                                                        key={pageNum}
                                                        onClick={() => handlePageChange(pageNum)}
                                                        className={`px-4 py-2 border rounded-lg transition ${
                                                            pagination.currentPage === pageNum
                                                                ? 'bg-purple-600 text-white'
                                                                : 'hover:bg-gray-100'
                                                        }`}
                                                    >
                                                        {pageNum}
                                                    </button>
                                                );
                                            } else if (
                                                pageNum === 2 ||
                                                pageNum === pagination.totalPages - 1
                                            ) {
                                                return <span key={pageNum} className="px-2">...</span>;
                                            }
                                            return null;
                                        })}

                                        <button
                                            onClick={() => handlePageChange(pagination.currentPage + 1)}
                                            disabled={pagination.currentPage === pagination.totalPages}
                                            className="px-4 py-2 border rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100 transition"
                                        >
                                            Next
                                        </button>
                                    </div>
                                )}
                            </>
                        )}
                    </>
                )}
            </div>
        </div>
    );
};

export default Events;
